#!/usr/bin/env bash
set -Eeuo pipefail
# NEW U01 USPS/MobileNetV3-Small/10ep — all 7 methods
# Static estimate: dataset is small; adaptive shared 5h45 cap; rerun same session with result ZIPs if not all fit
# HARD POLICY: this outer session shares one clock with every child task.
# PACK_SAFE_MINUTES=345 => planner deadline at 5h45 from outer start.
# 20 min are additionally reserved by each scientific task.
# No new GPU wave is launched if its measured estimate does not fit.

export PACK_SESSION_START_EPOCH="$(date +%s)"
export PACK_SAFE_MINUTES=345
export PACK_RESERVE_MINUTES=20
export PACK_SAFETY_FACTOR=1.25
SESSION_DIR="/kaggle/working/PAPER_COMPLETION_6H_SESSION"
rm -rf "$SESSION_DIR"; mkdir -p "$SESSION_DIR"

# Restore any prior resumable task ZIPs attached as Kaggle inputs.
python - <<'PYRESUME'
from pathlib import Path
import zipfile
for z in sorted(Path('/kaggle/input').rglob('*_results.zip')):
    try:
        with zipfile.ZipFile(z) as f:
            f.extractall('/kaggle/working')
        print('RESTORED', z)
    except Exception as e:
        print('SKIP_BAD_ZIP', z, repr(e))
PYRESUME

cat > "$SESSION_DIR/U01_linear.sh.b64" <<'B64_U01_linear_sh'

B64_U01_linear_sh
base64 -d "$SESSION_DIR/U01_linear.sh.b64" > "$SESSION_DIR/U01_linear.sh"
chmod +x "$SESSION_DIR/U01_linear.sh"
cat > "$SESSION_DIR/U01_dt1d.sh.b64" <<'B64_U01_dt1d_sh'

B64_U01_dt1d_sh
base64 -d "$SESSION_DIR/U01_dt1d.sh.b64" > "$SESSION_DIR/U01_dt1d.sh"
chmod +x "$SESSION_DIR/U01_dt1d.sh"
cat > "$SESSION_DIR/U01_bitfit.sh.b64" <<'B64_U01_bitfit_sh'

B64_U01_bitfit_sh
base64 -d "$SESSION_DIR/U01_bitfit.sh.b64" > "$SESSION_DIR/U01_bitfit.sh"
chmod +x "$SESSION_DIR/U01_bitfit.sh"
cat > "$SESSION_DIR/U01_ssf.sh.b64" <<'B64_U01_ssf_sh'

B64_U01_ssf_sh
base64 -d "$SESSION_DIR/U01_ssf.sh.b64" > "$SESSION_DIR/U01_ssf.sh"
chmod +x "$SESSION_DIR/U01_ssf.sh"
cat > "$SESSION_DIR/U01_conv_r4.sh.b64" <<'B64_U01_conv_r4_sh'

B64_U01_conv_r4_sh
base64 -d "$SESSION_DIR/U01_conv_r4.sh.b64" > "$SESSION_DIR/U01_conv_r4.sh"
chmod +x "$SESSION_DIR/U01_conv_r4.sh"
cat > "$SESSION_DIR/U01_bam.sh.b64" <<'B64_U01_bam_sh'

B64_U01_bam_sh
base64 -d "$SESSION_DIR/U01_bam.sh.b64" > "$SESSION_DIR/U01_bam.sh"
chmod +x "$SESSION_DIR/U01_bam.sh"
cat > "$SESSION_DIR/U01_full.sh.b64" <<'B64_U01_full_sh'

B64_U01_full_sh
base64 -d "$SESSION_DIR/U01_full.sh.b64" > "$SESSION_DIR/U01_full.sh"
chmod +x "$SESSION_DIR/U01_full.sh"

run_child() {
  local child="$1"
  local now elapsed left
  now="$(date +%s)"; elapsed=$((now-PACK_SESSION_START_EPOCH)); left=$((6*3600-elapsed))
  echo "============================================================"
  echo "NEXT=$child elapsed=$((elapsed/60))min hard_6h_left=$((left/60))min"
  echo "============================================================"
  if (( left < 2400 )); then echo "SESSION_STOP: <40 min hard-limit margin remains"; return 99; fi
  set +e
  bash "$SESSION_DIR/$child"
  local rc=$?
  set -e
  if (( rc != 0 )); then
    echo "CHILD_STOP rc=$rc child=$child"
    echo "Attach its *_results.zip next session and rerun this SAME grouped cell."
    return $rc
  fi
}

run_child "U01_linear.sh" || { rc=$?; echo "GROUP_STOPPED_AFTER_OR_AT U01_linear.sh rc=$rc"; exit 0; }
run_child "U01_dt1d.sh" || { rc=$?; echo "GROUP_STOPPED_AFTER_OR_AT U01_dt1d.sh rc=$rc"; exit 0; }
run_child "U01_bitfit.sh" || { rc=$?; echo "GROUP_STOPPED_AFTER_OR_AT U01_bitfit.sh rc=$rc"; exit 0; }
run_child "U01_ssf.sh" || { rc=$?; echo "GROUP_STOPPED_AFTER_OR_AT U01_ssf.sh rc=$rc"; exit 0; }
run_child "U01_conv_r4.sh" || { rc=$?; echo "GROUP_STOPPED_AFTER_OR_AT U01_conv_r4.sh rc=$rc"; exit 0; }
run_child "U01_bam.sh" || { rc=$?; echo "GROUP_STOPPED_AFTER_OR_AT U01_bam.sh rc=$rc"; exit 0; }
run_child "U01_full.sh" || { rc=$?; echo "GROUP_STOPPED_AFTER_OR_AT U01_full.sh rc=$rc"; exit 0; }

elapsed=$(( $(date +%s) - PACK_SESSION_START_EPOCH ))
echo "GROUP_COMPLETE elapsed=$((elapsed/60)) min"
if (( elapsed >= 6*3600 )); then echo "ERROR: outer session exceeded 6h"; exit 88; fi
